<?php
namespace Cyberfort\AIRegister; defined( 'ABSPATH' ) || exit;
class Api_Client { private Cache $cache; public function __construct() { $this->cache = new Cache(); } public function get_tenant(): array { return $this->request( 'tenant' ); } public function get_taxonomies(): array { return $this->request( 'taxonomies' ); } public function get_branding(): array { return $this->request( 'branding' ); } public function get_systems( array $params = [] ): array { return $this->request( 'systems', $params ); } public function get_system( string $reference ): array { return $this->request( 'systems/' . rawurlencode( $reference ) ); } public function test_connection(): array { return $this->get_tenant(); }
 private function request( string $endpoint, array $params = [] ): array { $language = ( new Language() )->resolve( $params['language'] ?? 'auto' ); $params['language'] = $language; $key = $this->cache->key( str_replace( '/', '_', $endpoint ), $params, $language ); if ( $cached = $this->cache->get( $key ) ) return $cached + [ 'cache' => 'fresh' ]; $url = $this->url( $endpoint, $params ); if ( is_wp_error( $url ) ) return [ 'error' => $url->get_error_message() ]; $start = microtime( true ); $response = wp_remote_get( $url, [ 'timeout' => 10, 'redirection' => 0, 'sslverify' => true, 'headers' => [ 'Authorization' => 'Bearer ' . get_option( 'cfair_api_key' ), 'Accept' => 'application/json', 'User-Agent' => 'Cyberfort-AI-Register-WordPress/' . CFAIR_VERSION . '; ' . home_url(), 'X-AIRegister-Plugin-Version' => CFAIR_VERSION, 'X-AIRegister-Site-URL' => home_url(), 'X-AIRegister-Language' => $language ] ] ); if ( is_wp_error( $response ) ) return $this->fallback( $key, $response->get_error_message() ); $status = wp_remote_retrieve_response_code( $response ); $body = wp_remote_retrieve_body( $response ); if ( 200 !== $status || strlen( $body ) > 1048576 ) return $this->fallback( $key, 'Remote service error (' . $status . ')' ); $data = json_decode( $body, true ); if ( ! is_array( $data ) ) return $this->fallback( $key, __( 'Malformed API response.', 'cyberfort-ai-register' ) ); $result = [ 'data' => $this->safe_data( $data ), 'timestamp' => time(), 'etag' => wp_remote_retrieve_header( $response, 'etag' ), 'latency_ms' => (int) ( ( microtime( true ) - $start ) * 1000 ) ]; $this->cache->put( $key, $result ); return $result; }
 private function url( string $endpoint, array $params ): string|\WP_Error { $server = (string) get_option( 'cfair_server_url' ); $parts = wp_parse_url( $server ); $dev = 'development' === get_option( 'cfair_environment' ) && defined( 'CFAIR_ALLOW_INSECURE_LOCALHOST' ) && CFAIR_ALLOW_INSECURE_LOCALHOST; if ( ! $parts || ! empty( $parts['query'] ) || ! empty( $parts['fragment'] ) || ( 'https' !== ( $parts['scheme'] ?? '' ) && ! $dev ) || empty( $parts['host'] ) ) return new \WP_Error( 'cfair_url', __( 'A valid HTTPS AI Register server URL is required.', 'cyberfort-ai-register' ) ); return add_query_arg( array_intersect_key( $params, array_flip( [ 'language', 'page', 'per_page', 'search', 'risk_tier', 'status', 'updated_after' ] ) ), untrailingslashit( $server ) . '/api/public/' . get_option( 'cfair_api_version', 'v1' ) . '/' . $endpoint ); }
 private function safe_data( array $data ): array { return json_decode( wp_json_encode( $data ), true ) ?: []; } private function fallback( string $key, string $error ): array { update_option( 'cfair_last_error', sanitize_text_field( $error ), false ); if ( $stale = $this->cache->stale( $key ) ) return $stale + [ 'cache' => 'stale' ]; return [ 'error' => $error ]; } }
